# cc-P760 (generated by make_shots.py): opens the Festival store and asks for shots of the window and its confirm step.
import API

SIG = r"D:/UO/golems/Iron/p760-proof/festival-signal.txt"
LOG = r"D:/UO/golems/Iron/p760-proof/festival.log"


def note(text):
    with open(LOG, "a") as f:
        f.write(text + "\n")
    API.SysMsg("P760: " + text)


def shot(name):
    with open(SIG, "a") as f:
        f.write("SHOT " + name + "\n")
    API.Pause(2)


API.Pause(4)
note("opening the Festival store with: festival")
API.Msg("festival")
API.Pause(4)
shot("festival-window")
API.ReplyGump(201)
API.Pause(4)
shot("festival-confirm")
if True:
    API.ReplyGump(1)
    API.Pause(4)
    shot("festival-after-buy")
note("done")
with open(SIG, "a") as f:
    f.write("DONE\n")
